package dev.veltraph.client.greenhouse;

import dev.veltraph.client.gui.*;
import java.util.*;
import org.junit.jupiter.api.*;
import net.minecraft.SharedConstants;
import net.minecraft.server.Bootstrap;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.RegistryAccess;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.ItemLore;
import dev.veltraph.client.inventory.NativeStackIdentity;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.greenhouse.GreenhouseModel.*;
import static dev.veltraph.client.greenhouse.GreenhouseDiagnosticAssociation.*;

class GreenhouseDiagnosticAssociationTest {
    static final Cell A=new Cell(0,70,0),B=new Cell(1,70,0);static final Object PLAYER=new Object(),WORLD=new Object(),CONNECTION=new Object(),OWNER=new Object();static final UUID TOKEN=UUID.randomUUID();
    static HolderLookup.Provider registry;
    @BeforeAll static void nativeRegistry(){registry=GreenhouseNativeTestBootstrap.lookup();}
    static ItemStack tool(){var s=new ItemStack(Items.STICK);s.set(DataComponents.CUSTOM_NAME,Component.literal("exact-tool"));return s;}
    static List<ItemStack> items(){var list=new ArrayList<ItemStack>();for(int i=0;i<36;i++)list.add(ItemStack.EMPTY);list.set(3,tool());list.set(11,new ItemStack(Items.DIAMOND,7));return list;}
    static Map<EquipmentSlot,ItemStack> gear(){var gear=new EnumMap<EquipmentSlot,ItemStack>(EquipmentSlot.class);for(var e:List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET,EquipmentSlot.OFFHAND))gear.put(e,ItemStack.EMPTY);return gear;}
    static GreenhouseNativeInventory nativeInventory(){return GreenhouseNativeInventory.capture(items(),gear(),ItemStack.EMPTY,3,registry);}
    static Selection selection(Cell cell){var cb=new GreenhouseBindings.CellBinding(cell,"Plant","minecraft:paper","Cell "+cell.x()+" 70 0","Crop: ","Empty","Growing","Ready","Dry","Watered","Stage: ","Water epoch: ","Growth: ","Decay: ",cell);return new Selection(new GreenhouseBindings("Same Diagnostics","p","plot","Profile: p","Plot: plot",nativeInventory().tool().persistentEncoding(),3,List.of(cb)),cell,0,"minecraft:paper","Sequence: ","Native target: ",1000);}
    static Custody custody(Cell cell){var inv=nativeInventory();return new Custody(PLAYER,WORLD,CONNECTION,OWNER,TOKEN,2,new Context("p","plot","dimension"),new Position(.5,70,2.5),17,12,3,inv.tool().identity(),inv,cell,"UP",new Position(cell.x()+.5,70,cell.z()+.5),"block","block",true,true,true);}
    static MenuSnapshot.Slot row(int id,String name,List<String> lore){var nativeRow=new ItemStack(Items.PAPER);nativeRow.set(DataComponents.CUSTOM_NAME,Component.literal(name));nativeRow.set(DataComponents.LORE,new ItemLore(lore.stream().map(Component::literal).map(c->(Component)c).toList()));return new MenuSnapshot.Slot(id,name,lore,false,"minecraft:paper",1,false,McMenuAccess.componentIdentity(nativeRow,registry));}
    static MenuSnapshot menu(Cell cell,int sequence){return new MenuSnapshot(3,"Same Diagnostics",List.of(row(0,"Plant",List.of("Profile: p","Plot: plot","Cell "+cell.x()+" 70 0","Crop: Wheat","Growing","Dry","Stage: 1","Sequence: "+sequence,"Native target: "+cell.x()+" 70 0"))),4);}
    static final Object SCREEN=new Object(),MENU=new Object();
    static final Map<GreenhouseDiagnosticAssociation,ReceiptToken> received=new IdentityHashMap<>();
    static ReceiptToken receipt(MenuSnapshot menu,long epoch){var row=menu.slots().stream().filter(r->r.id()==0).findFirst().orElseThrow();var stack=new ItemStack(Items.PAPER,row.count());stack.set(DataComponents.CUSTOM_NAME,Component.literal(row.name()));stack.set(DataComponents.LORE,new ItemLore(row.lore().stream().map(Component::literal).map(c->(Component)c).toList()));return new ReceiptToken(SCREEN,MENU,menu.id(),menu.revision(),epoch,menu.title(),row,NativeStackIdentity.capture(stack,registry));}
    static Optional<Associated> observe(GreenhouseDiagnosticAssociation r,MenuSnapshot menu,Map<Cell,String> states,Custody c,long time,long epoch){var token=receipt(menu,epoch);var a=r.observe(menu,states,c,time,epoch,token);if(a.isPresent())received.put(r,token);return a;}
    static boolean confirm(GreenhouseDiagnosticAssociation r,java.util.function.BooleanSupplier save,java.util.function.Supplier<Custody> custody){return r.confirmDurable(save,custody,()->received.get(r),()->11);}
    static GreenhouseDiagnosticAssociation issued(Cell c,int sequence){var r=new GreenhouseDiagnosticAssociation();assertTrue(r.begin(selection(c),custody(c),10,1,true));assertTrue(r.submitted(custody(c),sequence,c,"UP",custody(c).hitPosition(),10));r.nativeCallReturned(true);assertEquals(State.WAIT_MENU,r.state());return r;}
    @Test void recordsBeforeUseAndRequiresActualSubmittedSequence(){var r=new GreenhouseDiagnosticAssociation();assertTrue(r.begin(selection(A),custody(A),10,1,true));assertEquals(State.BEFORE_USE,r.state());assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,2).isEmpty());r.nativeCallReturned(true);assertEquals(State.UNKNOWN,r.state());}
    @Test void exactNewReceiptPersistsOnlySelectedNativeCell(){var r=issued(A,9);var a=observe(r,menu(A,9),Map.of(A,"block",B,"block"),custody(A),11,2).orElseThrow();assertEquals(A,a.evidence().cell());assertEquals(A,a.evidence().actualNativeTarget());assertEquals(9,a.evidence().nativeSequence());assertEquals("Wheat",a.evidence().plant().crop());assertEquals(State.ASSOCIATED,r.state());assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),12,3).isEmpty());}
    @Test void nearbySameMenuWrongCellDoesNotAssociate(){var r=issued(B,10);assertTrue(observe(r,menu(A,10),Map.of(B,"block"),custody(B),11,2).isEmpty());assertEquals(State.UNKNOWN,r.state());}
    @Test void lateOlderRequestCannotBindEvenSameTitleOrCell(){for(Cell c:List.of(A,B)){var r=issued(c,10);assertTrue(observe(r,menu(c,9),Map.of(c,"block"),custody(c),11,2).isEmpty());assertEquals(State.UNKNOWN,r.state());}}
    @Test void originalCapturedMenuWithoutEchoRemainsUnknown(){var r=issued(A,9);var m=menu(A,9);var nativeRow=m.slots().getFirst();var unbound=new MenuSnapshot(m.id(),m.title(),List.of(row(0,nativeRow.name(),nativeRow.lore().stream().filter(l->!l.startsWith("Sequence:")&&!l.startsWith("Native target:")).toList())),4);assertTrue(observe(r,unbound,Map.of(A,"block"),custody(A),11,2).isEmpty());assertEquals(State.UNKNOWN,r.state());}
    @Test void duplicateSubmissionsAndForeignActionInvalidate(){var r=issued(A,9);r.foreignNativeAction();assertEquals(State.UNKNOWN,r.state());r=new GreenhouseDiagnosticAssociation();assertTrue(r.begin(selection(A),custody(A),10,1,true));assertTrue(r.submitted(custody(A),9,A,"UP",custody(A).hitPosition(),10));assertFalse(r.submitted(custody(A),9,A,"UP",custody(A).hitPosition(),10));r.nativeCallReturned(true);assertEquals(State.UNKNOWN,r.state());}
    @Test void cancellationAndExactDeadlineBlockLateMenu(){var r=issued(A,9);r.cancel();assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,2).isEmpty());r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),1010,2).isEmpty());assertEquals(State.UNKNOWN,r.state());}
    @Test void oldMenuEpochClockAndForeignTitleBlockReceipt(){var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,1).isEmpty());assertEquals(State.UNKNOWN,r.state());r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),10,2).isEmpty());assertEquals(State.UNKNOWN,r.state());r=issued(A,9);assertTrue(observe(r,new MenuSnapshot(3,"Foreign",menu(A,9).slots(),4),Map.of(A,"block"),custody(A),11,2).isEmpty());assertEquals(State.UNKNOWN,r.state());}
    static Custody changed(Custody a,int which,GreenhouseNativeInventory inv){return new Custody(which==0?new Object():a.player(),which==1?new Object():a.world(),which==2?new Object():a.connection(),which==3?new Object():a.owner(),which==4?UUID.randomUUID():a.token(),which==5?a.epoch()+1:a.epoch(),which==6?new Context("other","plot","dimension"):a.context(),which==7?new Position(.51,70,2.5):a.position(),which==8?a.yaw()+1:a.yaw(),a.pitch(),inv.selectedSlot(),inv.tool().identity(),inv,a.rayCell(),a.face(),a.hitPosition(),a.targetFingerprint(),a.plantFingerprint(),true,true,which!=9);}
    @Test void scopeOwnerToolPoseCursorAndWorldDriftAreNotAllowed(){var a=custody(A);for(int i:List.of(0,3,5,8,9)){var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),changed(a,i,a.inventory()),11,2).isEmpty());assertEquals(State.UNKNOWN,r.state());}}
    @Test void protectedInventoryAndChangedPlantBlockExactReceipt(){var a=custody(A);var list=items();list.get(11).shrink(1);var altered=GreenhouseNativeInventory.capture(list,gear(),ItemStack.EMPTY,3,registry);var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),changed(a,-1,altered),11,2).isEmpty());assertEquals(State.UNKNOWN,r.state());r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"changed"),a,11,2).isEmpty());assertEquals(State.UNKNOWN,r.state());}
    @Test void durabilityRefusalLeavesNoAssociationPermission(){var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,2).isPresent());r.refuseDurability();assertEquals(State.UNKNOWN,r.state());assertTrue(r.associated().isEmpty());}
    @Test void onlyScalarObservedEvidenceIsArchived(){var r=issued(A,9);var a=observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,2).orElseThrow();var gson=new com.google.gson.Gson();String json=gson.toJson(a.evidence());assertFalse(json.contains(PLAYER.toString()));assertEquals("native-slot-integrity-v1",a.evidence().exactInventory().schema());assertEquals(a.evidence(),gson.fromJson(json,Evidence.class));}
    @Test void connectionWorldTokenProfilePositionAndToolDriftRejectMatchedEcho(){var a=custody(A);for(int i:List.of(1,2,4,6,7)){var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),changed(a,i,a.inventory()),11,2).isEmpty());assertEquals(State.UNKNOWN,r.state());}var list=items();list.get(3).set(DataComponents.CUSTOM_NAME,Component.literal("different-tool"));var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),changed(a,-1,GreenhouseNativeInventory.capture(list,gear(),ItemStack.EMPTY,3,registry)),11,2).isEmpty());assertEquals(State.UNKNOWN,r.state());}
    @Test void mixedHeaderAndStalePlantRowCannotAuthorize(){var header=row(0,"Header",List.of("Sequence: 9","Native target: 0 70 0"));var plant=row(7,"Plant",menu(A,9).slots().getFirst().lore().stream().filter(l->!l.startsWith("Sequence:")&&!l.startsWith("Native target:")).toList());var r=issued(A,9);assertTrue(observe(r,new MenuSnapshot(3,"Same Diagnostics",List.of(header,plant),4),Map.of(A,"block"),custody(A),11,2).isEmpty());assertEquals(State.UNKNOWN,r.state());}
    @Test void correctHeaderRowCannotBorrowProfileAndPlotFromAnotherRow(){var all=menu(A,9).slots().getFirst().lore();var selected=row(0,"Plant",all.stream().filter(l->!l.startsWith("Profile:")&&!l.startsWith("Plot:")).toList());var scope=row(7,"Scope",List.of("Profile: p","Plot: plot"));var r=issued(A,9);assertTrue(observe(r,new MenuSnapshot(3,"Same Diagnostics",List.of(selected,scope),4),Map.of(A,"block"),custody(A),11,2).isEmpty());assertEquals(State.UNKNOWN,r.state());}
    @Test void persistenceFalseAndThrowWithdrawExactCandidate(){for(boolean throwsFailure:List.of(false,true)){var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,2).isPresent());assertFalse(confirm(r,()->{if(throwsFailure)throw new IllegalStateException("disk failure");return false;},()->custody(A)));assertEquals(State.UNKNOWN,r.state());assertTrue(r.associated().isEmpty());}}
    @Test void successfulSaveCannotHidePostSaveNativeSlotMove(){var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,2).isPresent());var now=new java.util.concurrent.atomic.AtomicReference<>(custody(A));assertFalse(confirm(r,()->{var list=items();var value=list.get(11);list.set(11,ItemStack.EMPTY);list.set(12,value);now.set(changed(custody(A),-1,GreenhouseNativeInventory.capture(list,gear(),ItemStack.EMPTY,3,registry)));return true;},now::get));assertEquals(State.UNKNOWN,r.state());}
    @Test void saveCallbackAloneCannotAcknowledgeAnUnreceivedMenu(){var r=issued(A,9);var calls=new java.util.concurrent.atomic.AtomicInteger();assertFalse(confirm(r,()->{calls.incrementAndGet();return true;},()->custody(A)));assertEquals(0,calls.get());assertEquals(State.WAIT_MENU,r.state());}

    @Test void successfulSaveWithReentrantScreenOrMenuReplacementWithdrawsPermission(){
        for(boolean replaceScreen:List.of(true,false)){var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,2).isPresent());var original=received.get(r);var current=new java.util.concurrent.atomic.AtomicReference<>(original);
            assertFalse(r.confirmDurable(()->{current.set(new ReceiptToken(replaceScreen?new Object():original.screen(),replaceScreen?original.menu():new Object(),original.containerId(),original.revision(),original.menuEpoch(),original.title(),original.row(),original.nativeRow()));return true;},()->custody(A),current::get,()->11));assertEquals(State.UNKNOWN,r.state());assertTrue(r.associated().isEmpty());}
    }
    @Test void successfulSaveWithReentrantAuthorizingRowChangesWithdrawsPermission(){
        for(String changed:List.of("Profile: other","Plot: other","Crop: other","Stage: 2")){var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,2).isPresent());var original=received.get(r);var current=new java.util.concurrent.atomic.AtomicReference<>(original);
            assertFalse(r.confirmDurable(()->{var lore=new ArrayList<>(original.row().lore());String prefix=changed.substring(0,changed.indexOf(':')+1);lore.removeIf(l->l.startsWith(prefix));lore.add(changed);var changedMenu=new MenuSnapshot(original.containerId(),original.title(),List.of(row(0,"Plant",lore)),original.revision());current.set(receipt(changedMenu,original.menuEpoch()));return true;},()->custody(A),current::get,()->11));assertEquals(State.UNKNOWN,r.state());}
    }
    @Test void sameVisibleRowWithChangedNativeComponentCannotPassSave(){var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,2).isPresent());var original=received.get(r);var current=new java.util.concurrent.atomic.AtomicReference<>(original);
        assertFalse(r.confirmDurable(()->{var item=new ItemStack(Items.PAPER);item.set(DataComponents.CUSTOM_NAME,Component.literal(original.row().name()));item.set(DataComponents.LORE,new ItemLore(original.row().lore().stream().map(Component::literal).map(c->(Component)c).toList()));item.set(DataComponents.MAX_STACK_SIZE,16);current.set(new ReceiptToken(original.screen(),original.menu(),original.containerId(),original.revision(),original.menuEpoch(),original.title(),original.row(),NativeStackIdentity.capture(item,registry)));return true;},()->custody(A),current::get,()->11));assertEquals(State.UNKNOWN,r.state());}
    @Test void saveCannotCrossTheOriginalRequestDeadline(){var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,2).isPresent());var clock=new java.util.concurrent.atomic.AtomicLong(11);assertFalse(r.confirmDurable(()->{clock.set(1010);return true;},()->custody(A),()->received.get(r),clock::get));assertEquals(State.UNKNOWN,r.state());}
    @Test void oldMenuRevisionEpochOrRollbackBeforeSaveDeniesWithoutCallback(){for(int kind=0;kind<3;kind++){var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,2).isPresent());var original=received.get(r);final int change=kind;var calls=new java.util.concurrent.atomic.AtomicInteger();var altered=new ReceiptToken(original.screen(),original.menu(),original.containerId(),kind==0?original.revision()+1:original.revision(),kind==1?original.menuEpoch()+1:original.menuEpoch(),original.title(),original.row(),original.nativeRow());assertFalse(r.confirmDurable(()->{calls.incrementAndGet();return true;},()->custody(A),()->altered,()->change==2?10:11));assertEquals(0,calls.get());assertEquals(State.UNKNOWN,r.state());}}
    @Test void exactReceivedTokenAndWithinDeadlineSuccessfulSaveRemainsMatched(){var r=issued(A,9);assertTrue(observe(r,menu(A,9),Map.of(A,"block"),custody(A),11,2).isPresent());assertTrue(confirm(r,()->true,()->custody(A)));assertEquals(State.ASSOCIATED,r.state());}

}
